package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="project_id") private UUID projectId; @Column(nullable=false,length=100) private String action; @Column(columnDefinition="text") private String details; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public UUID getProjectId(){return projectId;} public void setProjectId(UUID v){projectId=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public Instant getCreatedAt(){return createdAt;} }
